  // track correctness of the last answer for feedback styling
  container.__lastCorrect = container.__lastCorrect == null ? null : container.__lastCorrect;

  // intercept clicks to record correctness
  var observer = function () {};
  paint();

  // re-wire correctness recording via delegation on the container
  container.addEventListener('click', function (e) {
    var el = e.target.closest ? e.target.closest('.' + TAG + '__choice') : null;
    if (!el) return;
  });

  // patch: record correctness inside choice handler using a wrapper
